/* Reset & Global Box Sizing */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --color-bg: #14182e;
  --color-surface: #252b48;
  --color-border: #0b0e1b;
  --color-accent: #f77622;
  --color-highlight: #ffe043;
  --color-text: #f4f4f4;
  --color-muted: #8b97b6;
  --color-success: #68c244;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.app-header {
  text-align: center;
}

.title {
  font-size: 24px;
  color: var(--color-highlight);
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--color-border);
}

.subtitle {
  font-size: 16px;
  color: var(--color-muted);
  margin-top: 4px;
}

/* Pixel Card Container */
.card {
  width: 100%;
  background-color: var(--color-surface);
  border: 4px solid var(--color-border);
  box-shadow: 6px 6px 0 var(--color-border);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.speaker-display {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label {
  font-size: 16px;
  color: var(--color-muted);
  font-weight: bold;
  letter-spacing: 1px;
}

.current-name {
  font-size: 28px;
  color: var(--color-highlight);
  font-weight: bold;
  letter-spacing: 1px;
  text-shadow: 1px 1px 0 var(--color-border);
}

/* Timer Display */
.timer-box {
  background-color: var(--color-bg);
  border: 4px solid var(--color-border);
  padding: 18px;
  text-align: center;
  box-shadow: inset 3px 3px 0 rgba(0, 0, 0, 0.4);
  margin: 8px 0;
}

.timer-digits {
  font-size: 48px;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--color-accent);
  display: block;
  text-shadow: 2px 2px 0 var(--color-border);
}

/* Pixel Button Styles */
.controls {
  display: flex;
  justify-content: center;
  margin-top: 4px;
}

.pixel-btn {
  appearance: none;
  background-color: var(--color-accent);
  color: #ffffff;
  border: 4px solid var(--color-border);
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 12px 28px;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--color-border);
  transition: transform 0.05s ease, background-color 0.1s ease;
  outline: none;
  min-width: 160px;
}

.pixel-btn:hover {
  background-color: #ff8e43;
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-highlight);
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--color-border);
}

/* Completed View */
.completed-container {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 12px 0;
}

.over-text {
  font-size: 32px;
  color: var(--color-highlight);
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--color-border);
}

.over-subtext {
  color: var(--color-muted);
  font-size: 16px;
}

/* Roster List */
.roster-section {
  border-top: 3px dashed var(--color-border);
  padding-top: 16px;
}

.roster-title {
  font-size: 16px;
  color: var(--color-muted);
  letter-spacing: 1px;
  margin-bottom: 12px;
}

.roster-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.roster-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  font-size: 16px;
  color: var(--color-text);
}

.roster-item.active {
  border-color: var(--color-highlight);
  background-color: #2e355c;
  color: var(--color-highlight);
  font-weight: bold;
}

.roster-item.active::before {
  content: "▶ ";
  color: var(--color-highlight);
}

.roster-item.done {
  color: var(--color-muted);
  text-decoration: line-through;
  opacity: 0.75;
}

.roster-item.done::after {
  content: " ✓";
  color: var(--color-success);
  text-decoration: none;
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  .timer-digits {
    font-size: 38px;
  }
  .pixel-btn {
    width: 100%;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const DEFAULT_SECONDS = 90;
  const SPEAKERS = ["Alex", "Sam", "Jordan", "Taylor"];

  let currentSpeakerIndex = 0;
  let secondsRemaining = DEFAULT_SECONDS;
  let timerInterval = null;

  const activeView = document.getElementById("active-view");
  const completedView = document.getElementById("completed-view");
  const currentSpeakerNameEl = document.getElementById("current-speaker-name");
  const timerDisplayEl = document.getElementById("timer-display");
  const nextBtn = document.getElementById("next-btn");
  const restartBtn = document.getElementById("restart-btn");
  const rosterListEl = document.getElementById("roster-list");

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    const paddedSeconds = seconds < 10 ? `0${seconds}` : `${seconds}`;
    return `${minutes}:${paddedSeconds}`;
  }

  function renderRoster() {
    rosterListEl.innerHTML = "";
    SPEAKERS.forEach((name, index) => {
      const li = document.createElement("li");
      li.className = "roster-item";

      if (currentSpeakerIndex < SPEAKERS.length) {
        if (index === currentSpeakerIndex) {
          li.classList.add("active");
          li.setAttribute("aria-current", "true");
        } else if (index < currentSpeakerIndex) {
          li.classList.add("done");
        }
      } else {
        li.classList.add("done");
      }

      const nameSpan = document.createElement("span");
      nameSpan.textContent = `${index + 1}. ${name}`;
      li.appendChild(nameSpan);
      rosterListEl.appendChild(li);
    });
  }

  function updateActiveSpeakerUI() {
    if (currentSpeakerIndex < SPEAKERS.length) {
      currentSpeakerNameEl.textContent = SPEAKERS[currentSpeakerIndex];
      timerDisplayEl.textContent = formatTime(secondsRemaining);
      activeView.removeAttribute("hidden");
      completedView.setAttribute("hidden", "");
    } else {
      stopTimer();
      activeView.setAttribute("hidden", "");
      completedView.removeAttribute("hidden");
    }
    renderRoster();
  }

  function tick() {
    if (secondsRemaining > 0) {
      secondsRemaining -= 1;
      timerDisplayEl.textContent = formatTime(secondsRemaining);
      if (secondsRemaining === 0) {
        goToNextSpeaker();
      }
    } else {
      goToNextSpeaker();
    }
  }

  function startTimer() {
    stopTimer();
    timerInterval = setInterval(tick, 1000);
  }

  function stopTimer() {
    if (timerInterval !== null) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function goToNextSpeaker() {
    currentSpeakerIndex += 1;
    if (currentSpeakerIndex < SPEAKERS.length) {
      secondsRemaining = DEFAULT_SECONDS;
      updateActiveSpeakerUI();
      startTimer();
    } else {
      updateActiveSpeakerUI();
    }
  }

  function restartStandup() {
    currentSpeakerIndex = 0;
    secondsRemaining = DEFAULT_SECONDS;
    updateActiveSpeakerUI();
    startTimer();
    nextBtn.focus();
  }

  nextBtn.addEventListener("click", () => {
    goToNextSpeaker();
  });

  restartBtn.addEventListener("click", () => {
    restartStandup();
  });

  // Initialize
  secondsRemaining = DEFAULT_SECONDS;
  updateActiveSpeakerUI();
  startTimer();
});
